  {"id": "round-goby", "name": "Round Goby", "sci": "Neogobius melanostomus", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "7-15 cm", "habitat": "Rocky and gravel bottoms of the Great Lakes and connected waters.", "tips": "Fused pelvic fins form a single suction disc on the belly, and there is a distinct black spot on the first dorsal fin.", "fact": "An invader from the Black and Caspian Seas that arrived in ballast water and now displaces native bottom fish.", "seasons": ["summer"], "activity": "diurnal", "seen": "common", "status": "Invasive", "atRisk": false, "caution": "Invasive—never use or transport it as bait, which is illegal in Ontario.", "region": "Great Lakes and connected waters", "angling": "Usually hooked incidentally on bottom baits; do not keep alive or move it between waters."},
  {"id": "white-sucker", "name": "White Sucker", "sci": "Catostomus commersonii", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "30-50 cm", "habitat": "A wide range from streams to lakes; forages on the bottom.", "tips": "Ventral, sucker-like mouth with thick fleshy lips; rounded body with scales that grow smaller toward the head.", "fact": "Ascends streams in large spring spawning runs and is an important forage and bait fish.", "seasons": ["spring"], "activity": "varies", "seen": "common", "status": "Not at risk", "atRisk": false, "caution": "", "region": "Widespread across the province", "angling": "Still-fish worms on the bottom of rivers during the spring run; also widely used as bait."},
  {"id": "bowfin", "name": "Bowfin", "sci": "Amia calva", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "45-75 cm", "habitat": "Warm, weedy, slow or still backwaters and marshy lake bays.", "tips": "Very long spineless dorsal fin and a rounded tail; males show a black eyespot near the tail base.", "fact": "A living fossil that can gulp air at the surface to survive in low-oxygen water.", "seasons": ["spring", "summer"], "activity": "crepuscular", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "Strong jaws and sharp teeth—keep fingers clear when unhooking.", "region": "Southern and central Ontario", "angling": "Bottom-fish cut bait or work lures in weedy backwaters for a dogged, hard-pulling fight."},
  {"id": "burbot", "name": "Burbot", "sci": "Lota lota", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "40-70 cm, occasionally larger", "habitat": "Deep, cold lakes and large rivers; the only freshwater member of the cod family.", "tips": "Elongated, mottled brown body with a single chin barbel, long soft dorsal and anal fins, and a rounded tail.", "fact": "Also called ling or eelpout, it spawns under the ice in midwinter, sometimes in writhing spawning balls.", "seasons": ["winter", "spring"], "activity": "nocturnal", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "", "region": "Great Lakes and cold inland lakes across the province", "angling": "Jig glow spoons, jigs, or cut bait on or near bottom after dark—a prime winter ice-fishing target and excellent eating ('poor man's lobster')."},
  {"id": "channel-catfish", "name": "Channel Catfish", "sci": "Ictalurus punctatus", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "40-75 cm", "habitat": "Large warm rivers and lakes with current and deep holes.", "tips": "Deeply forked tail, a rounded anal fin, and scattered dark spots on young fish.", "fact": "Its skin is covered in taste buds, letting it 'taste' with virtually its whole body.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "Sharp pectoral and dorsal spines can cause painful punctures.", "region": "Southern rivers and the lower Great Lakes (e.g., Lake St. Clair, Grand River)", "angling": "Bottom-fish cut bait, chicken liver, or stinkbait in rivers, especially after dark."},
  {"id": "lake-sturgeon", "name": "Lake Sturgeon", "sci": "Acipenser fulvescens", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "90-150 cm, to over 2 m", "habitat": "Deep pools of large rivers and lakes; feeds on the bottom.", "tips": "Rows of bony scutes, a shark-like (heterocercal) tail, and four barbels ahead of a toothless, protrusible sucker mouth.", "fact": "A living relic that can live over 100 years and exceed 100 kg.", "seasons": ["spring", "summer"], "activity": "nocturnal", "seen": "uncommon", "status": "Threatened to Endangered (varies by population)", "atRisk": true, "caution": "Protected—release unharmed; scutes are sharp. Seasons are closed in many waters, so check regulations first.", "region": "Great Lakes and large northern rivers", "angling": "Catch-and-release only in most waters; where legal, still-fish bottom baits and handle with great care."},
  {"id": "longnose-gar", "name": "Longnose Gar", "sci": "Lepisosteus osseus", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "60-100 cm", "habitat": "Warm, weedy bays and slow-moving rivers.", "tips": "Very long, narrow, tooth-lined beak (over twice the head length) and diamond-shaped, armour-like ganoid scales.", "fact": "An ancient fish whose interlocking bony scales and long jaws have changed little in millions of years.", "seasons": ["spring", "summer"], "activity": "diurnal", "seen": "uncommon", "status": "Not at risk", "atRisk": false, "caution": "Sharp teeth, and its roe (eggs) is toxic to humans—never eat the eggs.", "region": "Southern Ontario (Great Lakes, Kawarthas)", "angling": "Tempt them in warm shallow bays with frayed nylon 'rope lures' (no hook) or live minnows."},
  {"id": "sea-lamprey", "name": "Sea Lamprey", "sci": "Petromyzon marinus", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "30-60 cm", "habitat": "Great Lakes; ascends tributary streams to spawn.", "tips": "Eel-like and jawless, with a round tooth-filled sucker mouth and seven gill pores along each side.", "fact": "This jawless parasite devastated Great Lakes trout stocks and is now held in check by targeted lampricide programs.", "seasons": ["spring"], "activity": "nocturnal", "seen": "uncommon", "status": "Invasive", "atRisk": false, "caution": "Invasive parasite—do not transport or return live where control programs apply.", "region": "Great Lakes and their tributaries", "angling": "Not an angling target; report sightings and do not move live specimens between waters."},
  {"id": "american-eel", "name": "American Eel", "sci": "Anguilla rostrata", "cat": "fish", "sub": "other-fish", "emoji": "🐟", "size": "60-100 cm, females larger", "habitat": "Rivers, lakes, and connected waters of the Lake Ontario and Ottawa River systems; catadromous, migrating to sea to spawn.", "tips": "Snake-like body with a single long dorsal fin continuous with the tail, smooth slippery skin with tiny embedded scales, and a projecting lower jaw.", "fact": "Every American Eel is born in the Atlantic's Sargasso Sea and drifts thousands of kilometres to Ontario fresh water, then returns to sea to spawn once and die.", "seasons": ["summer", "fall"], "activity": "nocturnal", "seen": "rare", "status": "Endangered (SARO)", "atRisk": true, "caution": "Endangered and protected in Ontario—it is illegal to fish for, keep, or harm American Eel; release any caught incidentally, unharmed.", "region": "Lake Ontario, the St. Lawrence, and the Ottawa River watershed", "angling": "Not a legal angling target in Ontario—the fishery is closed. Release any eel hooked incidentally and report sightings to the MNR."}
